# A simple file search function using indexing for a repository.

import os
import json
from collections import defaultdict

class RepoSearch:
    def __init__(self, repo_path):
        self.repo_path = repo_path
        self.index = {}
        self.build_index()

    def build_index(self):
        # Traverse the repository and build an index of file contents
        for root, _, files in os.walk(self.repo_path):
            for file in files:
                file_path = os.path.join(root, file)
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        content = f.read()
                        self.index[file_path] = content
                except Exception as e:
                    print(f'Error reading {file_path}: {e}')

    def search(self, query):
        # Search for the query in the indexed file contents
        results = defaultdict(list)
        for file_path, content in self.index.items():
            if query.lower() in content.lower():
                results[query].append(file_path)
        return results

if __name__ == '__main__':
    repo_path = '/path/to/your/repo'
    search_engine = RepoSearch(repo_path)
    query = input('Enter search query: ')
    results = search_engine.search(query)
    for q, files in results.items():
        print(f'Files containing "{q}":')
        for file in files:
            print(file)
